const subaruCatalyst={label:"Subaru Bulletin 09-110-23R — P0420 diagnostic procedure",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10246083-0001.pdf",note:"Covers 2018–2023 WRX and requires misfire, mixture, sensor, oil-smoke and exhaust checks plus model-specific SSM verification"};
