const subaruRearSensor={label:"Subaru Bulletin 09-115-24 — rear oxygen-sensor design change",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11000828-0001.pdf",note:"Lists Outback, Impreza/Crosstrek, Forester and BRZ applications but not WRX; useful chiefly to prevent misapplying that sensor branch"};

