const misfire17={label:"Hyundai TSB 20-FL-001H — 2017 Elantra 2.0L misfire",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10172218-0001.pdf",note:"Narrow 2017 AD/ADA 2.0L ECM update and ignition-coil inspection path for P0300–P0304"};
const nInjectors={label:"Hyundai TSB 24-FL-006H — selected 2022 Elantra N injectors",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11009770-0001.pdf",note:"Limited production-date/VIN-origin 2022 Elantra N 2.0T branch for P0300–P0304 caused by injector internal filter breakage"};

const wrx={name:"Subaru WRX",kicker:"SUBARU WRX · TURBO BOXER ENGINE DIAGNOSTICS",breadcrumb:"Subaru WRX",about:"Subaru WRX turbo engine and emissions diagnostics",yearsIntro:"WRX diagnostics span EJ20/EJ255 turbo models, FA20DIT direct injection and the newer FA24DIT, while STI variants retain different EJ257 hardware in many years. Intake/exhaust AVCS coverage, turbo and EGR plumbing, cylinder banks, fuel systems, catalysts and ECM monitor thresholds are not interchangeable. Confirm VIN, model year, WRX versus STI, engine code, transmission, emissions label and ECM calibration before using any test or bulletin."};
const elantra={name:"Hyundai Elantra",kicker:"HYUNDAI ELANTRA · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Hyundai Elantra",about:"Hyundai Elantra engine and emissions diagnostics",yearsIntro:"Elantra diagnostics span multiple sedan, Coupe, GT, Sport, N Line, Hybrid and Elantra N generations with Beta, Gamma, Nu, Kappa, Smartstream and Theta-family engines. MPI, GDI, turbocharging, CVVT, intake-runner hardware, EVAP design and campaign coverage differ sharply. Confirm VIN, body style, model year, engine code, production date, market and ECM ROM before applying any bulletin, definition or component diagram."};

export const troubleCodeWrx:TroubleCodeGuide[]=[
 make(wrx,{code:"P0420",slug:"subaru/wrx/p0420",title:"P0420 Code Subaru WRX: Turbo Catalyst Diagnosis",description:"Diagnose WRX P0420 with Subaru's SSM procedure, misfire and mixture prerequisites, turbo exhaust inspection and model-specific thresholds.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means the WRX ECM calculated insufficient Bank 1 catalyst oxygen storage; it does not prove the converter alone failed. Subaru bulletin 09-110-23R covers 2018–2023 WRX, screens P0300–P0304, P0171/P0172 and P0137-series faults, checks oil smoke and exhaust leakage, and uses different SSM thresholds for 2018–2021 2.5L turbo and 2022-and-newer 2.4L DIT manual/CVT applications. Repair catalyst-damaging causes before replacing exhaust parts.",yearNotes:["09-110-23R names 2018–2023 WRX; other years require their current STIS route.","The bulletin separates 2.5L turbo from 2.4L DIT and even MT from CVT thresholds.","Aftermarket downpipes or tuning can invalidate stock monitor assumptions and emissions legality.","A flashing MIL requires reducing load immediately."],deepDive:[{heading:"The WRX threshold is engine and transmission specific",paragraphs:["Subaru publishes different SSM catalyst-deterioration values for 2018–2021 2.5L turbo and 2022-plus 2.4L DIT. The later manual and CVT verification values also differ, so a generic rear-sensor graph is incomplete.","Identify WRX versus STI, engine, transmission and ECM calibration before running the road pattern. Modified exhaust or software must be documented because factory monitor expectations may no longer match the installed system."]},{heading:"Turbo problems can make the catalyst a victim",paragraphs:["Review boost-related misfire, injector balance, fuel correction, oil consumption and turbo oil leakage. Raw fuel and oil ash can damage a replacement converter if the upstream cause remains.","Inspect cylinder-head joints, turbo/exhaust connections, front pipe, converter and sensor bungs cold for soot or air leakage. Subaru's bulletin requires the general and exhaust inspections before its active A/F test."]},{heading:"Use Subaru's active test and monitor proof",paragraphs:["The published procedure commands injection quantity and checks whether the A/F sensor reaches target before choosing the sensor or exhaust branch. It then uses Inspection Mode V and SSM monitor data rather than visual waveform resemblance alone.","Complete the prescribed verification with no pending P0420. Clearing the lamp, installing an extender or seeing incomplete readiness does not prove catalyst efficiency."]}],sources:[subaruCatalyst,stis,subaruOwners]}),
 make(wrx,{code:"P0171",slug:"subaru/wrx/p0171",title:"P0171 Code Subaru WRX: Turbo Lean Diagnosis",description:"Diagnose WRX P0171 with idle/boost fuel correction, inlet and charge leak tests, purge, MAF, fuel pressure and A/F feedback.",definition:"System Too Lean (Bank 1)",kind:"lean",quickAnswer:"P0171 means the WRX ECM reached excessive positive Bank 1 fuel correction. Save A/F correction and learning at idle, cruise and safe boost before resetting. Idle-heavy correction favors a post-MAF inlet, PCV, brake-booster or purge leak; correction worsening with load raises MAF scaling, charge leakage or fuel delivery. FA20DIT and FA24DIT high-pressure systems require factory safety procedures. A modified intake or calibration must be disclosed because it can create systematic airflow error.",yearNotes:["EJ, FA20DIT and FA24DIT fuel and airflow strategies differ.","Vacuum-side and pressurized charge-side leaks may show different trim patterns.","Aftermarket intakes, boost control and tunes change stock MAF/load assumptions.","Direct-injection rail work requires trained high-pressure handling."],deepDive:[{heading:"Map correction from vacuum into boost",paragraphs:["Record correction at hot idle, steady cruise and a controlled loaded condition. A split turbo inlet may draw unmetered air under vacuum, while an intercooler connection can leak chiefly as pressure rises.","Compare requested and actual boost, MAF, manifold pressure and calculated load. Do not repeatedly enter boost with severe lean correction or active misfire."]},{heading:"Smoke and pressure tests answer different questions",paragraphs:["Smoke the post-MAF inlet, PCV and manifold at safe pressure, then use the engine-specific charge-system method for intercooler and bypass plumbing. Excessive shop pressure can create damage and false leaks.","Command purge closed and verify actual sealing. A purge valve that clicks but passes flow can create idle correction and refueling symptoms."]},{heading:"Validate both fuel stages and feedback",paragraphs:["On direct-injected WRXs, compare low-side supply with commanded and actual high-side pressure under the fault condition. Use GDS/SSM-safe procedures and never loosen a high-pressure line casually.","Inspect pre-sensor exhaust leaks and verify A/F response before replacement. Final proof is stable correction near target under original conditions with no pending P0171."]}],sources:[stis,subaruOwners]}),
 make(wrx,{code:"P0300",slug:"subaru/wrx/p0300",title:"P0300 Code Subaru WRX: Boost and Boxer Misfire Diagnosis",description:"Diagnose WRX P0300 using roughness counts, bank patterns, plugs, coils, injectors, fuel pressure, compression and AVCS data.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means several WRX cylinders misfired or no one cylinder dominated. Save P0301–P0304 companions, roughness counts, fuel correction, boost, rail pressure, temperature and load before moving parts. Cold-only, boost-only, one-cylinder, one-bank and all-cylinder patterns require different tests. Spark-plug gap or weak ignition may appear under cylinder pressure, but injector, fuel delivery, intake leakage, compression and AVCS timing still need evidence. Stop loading the engine when the MIL flashes.",yearNotes:["EJ coil-on-plug, FA direct injection and STI hardware use different tests and cylinder layouts.","Boost-only misfire should not be reproduced repeatedly with a flashing lamp.","Modified calibration, fuel and spark-plug specification must be recorded.","P0011/P0021 companions move AVCS and oil control higher."],deepDive:[{heading:"Preserve roughness counts under the actual condition",paragraphs:["Capture cold-start, idle and controlled-load counters before cycling the key or moving coils. Label every plug and make one comparison at a time so the cylinder pattern remains usable.","One-bank accumulation raises local intake, exhaust or cam-control causes. Counts across all cylinders raise shared fuel pressure, MAF, voltage, contaminated fuel or calibration questions."]},{heading:"Boost raises ignition and delivery demand together",paragraphs:["Inspect gap, insulator cracks, fuel wetness and oil ash on labeled plugs. A breakdown that appears only under boost can be ignition reserve, but commanded versus actual rail pressure must be recorded at the same time.","If the fault stays on a cylinder after a valid ignition test, check injector contribution and compression/leak-down. Direct-injection equipment and depressurization procedures are mandatory on FA engines."]},{heading:"Mechanical and calibration context matters",paragraphs:["AVCS errors, valve sealing, timing indexing and engine modifications can create structured misfire. Do not replace four coils because a generic description says random.","Verify stable counts under the original safe condition and no pending P0300. Repair combustion first, then assess any P0420 catalyst consequence."]}],sources:[subaruCatalyst,stis,subaruOwners]}),
 make(wrx,{code:"P0028",slug:"subaru/wrx/p0028",title:"P0028 Code Subaru WRX: Verify the Engine and Scan Definition",description:"Understand why WRX P0028 requires raw-code and engine verification before applying naturally aspirated Subaru AVLS diagnosis.",definition:"Intake Valve Control Solenoid Circuit Range/Performance (Bank 2) — Application Must Be Verified",kind:"applicationCheck",quickAnswer:"Do not order an AVLS pressure switch or intake valve-lift solenoid for a WRX from P0028 wording alone. Subaru's P0028 factory procedure is associated with applicable naturally aspirated SOHC/AVLS engine documentation, while WRX turbo EJ and FA engines use different AVCS hardware and code sets. Record the raw code and reporting module, decode the engine, re-scan with Subaru-capable equipment and compare the ECM calibration with installed hardware. Engine swaps, market differences, generic code databases and controller mismatches must be excluded first.",yearNotes:["WRX and a naturally aspirated Impreza are not interchangeable simply because their chassis names overlap.","AVLS valve lift and AVCS cam phasing are different systems.","Turbo EJ, FA20DIT and FA24DIT hardware varies by year and market.","An engine/ECM swap makes identification and calibration matching essential."],deepDive:[{heading:"The code phrase exists, but the named WRX hardware may not",paragraphs:["Subaru service documentation places P0028 under applicable SOHC naturally aspirated intake-valve-control diagnosis. A WRX turbo manual instead documents its own AVCS and cam-timing code set.","A generic scanner can display the standardized P0028 phrase without validating whether the production WRX configuration supports that monitor. Treat that mismatch as the first diagnostic fact."]},{heading:"Prove the module, engine and calibration identity",paragraphs:["Save raw hexadecimal data, DTC status, freeze frame and the controller that reported it. Decode the VIN, read the ECM calibration and inspect the installed engine code, noting swaps or imported-market parts.","If Subaru-capable scanning produces a different manufacturer description or no current P0028, correct the profile or communication issue. Do not create a repair around a database label."]},{heading:"Only test a valve system after applicability is proven",paragraphs:["If the exact engine manual confirms a Bank 2 intake valve-control monitor, follow that manual's switch, solenoid, oil and circuit procedure. If the car has WRX AVCS instead, diagnose its actual current cam/oil-control codes.","Verification is coherent engine/ECM identification and a repeat manufacturer scan without unsupported P0028. Clearing the anomaly before preserving its source loses the evidence."]}],sources:[wrxService,stis,subaruOwners]}),
 make(wrx,{code:"P0011",slug:"subaru/wrx/p0011",title:"P0011 Code Subaru WRX: Bank 1 Intake AVCS Diagnosis",description:"Diagnose WRX P0011 with oil prerequisites, desired/actual intake timing, solenoid current and cam/crank correlation by engine.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 1)",kind:"subaruVvt",quickAnswer:"P0011 means the WRX Bank 1 intake cam remained more advanced than commanded or failed AVCS performance. Confirm EJ, FA20DIT or FA24DIT and WRX versus STI; save both-bank requested/actual angles, oil temperature and companion codes; verify oil and pressure; then test the Bank 1 intake oil-control valve and circuit. Subaru bulletin 18-210-21 documents added 2015–2016 WRX/STI diagnostic steps, but current STIS controls and the DTC does not prove the valve or timing chain failed.",yearNotes:["WRX, STI, EJ, FA20 and FA24 AVCS layouts are not interchangeable.","18-210-21 documents service-manual revisions rather than a universal parts repair.","Both-bank faults raise shared oil, voltage and base-timing priority.","Persistent rattle or low oil pressure requires stopping."],deepDive:[{heading:"Compare both banks at the same oil temperature",paragraphs:["Record desired and actual intake angle at idle and controlled rpm. A Bank 1-only over-advance supports local valve, circuit, oil passage, phaser or feedback testing; both banks point toward shared prerequisites.","Verify oil level, exact viscosity, filter and pressure first. Turbo heat can make a marginal hydraulic response appear only when oil is hot."]},{heading:"Test command and movement separately",paragraphs:["Measure oil-control-valve current and loaded circuit voltage, then confirm the cam actually follows and returns. A clicking solenoid does not prove correct metering or passage flow.","Use only engine-specific comparison procedures and one-time seals. Do not copy an FB-engine valve-swap instruction into an EJ or FA WRX without STIS authorization."]},{heading:"Waveforms prevent unnecessary timing teardown",paragraphs:["Missing or noisy cam edges favor a sensor, connector or harness issue. Clean signals with a stable offset, rattle and failed commanded response move phaser or mechanical timing higher.","Complete required learning and inspection mode after repair. Correct Bank 1 tracking with no pending P0011 confirms the result."]}],sources:[wrxService,stis,subaruOwners]}),
 make(wrx,{code:"P0021",slug:"subaru/wrx/p0021",title:"P0021 Code Subaru WRX: Bank 2 Intake AVCS Diagnosis",description:"Diagnose WRX P0021 using Bank 2 requested/actual cam angle, oil-control circuit, pressure and correlation evidence.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 2)",kind:"subaruVvt",quickAnswer:"P0021 means the WRX Bank 2 intake cam stayed more advanced than commanded or failed AVCS performance. Identify the exact EJ, FA20DIT or FA24DIT system, preserve both-bank angle and oil data, verify lubrication, then test the Bank 2 intake control valve, wiring and actual cam response. Subaru service-manual revisions add WRX/STI diagnostic steps for covered years, but P0021 alone does not establish a solenoid, phaser or chain repair. P0028 is a separate application-sensitive valve-control code.",yearNotes:["Bank location and sensor/valve layout must come from the exact WRX or STI manual.","P0011 plus P0021 favors shared oil, voltage or base timing.","Engine modifications can change commanded angle and load context.","Current STIS supersedes locally saved older procedures."],deepDive:[{heading:"Use Bank 1 as a controlled comparison",paragraphs:["Graph both intake cams under identical rpm, load and oil temperature. A Bank 2-only response error narrows the local electrical, hydraulic and mechanical branches.","If both banks remain advanced, inspect oil pressure, supply voltage, common control and base timing before ordering two valves."]},{heading:"A resistance check is not an AVCS performance test",paragraphs:["Load-test wiring and terminal grip, measure current and observe physical cam movement. Restricted oil flow or a sticking phaser can leave electrical measurements normal.","Document oil service history and any debris found in approved screens or passages. Contamination can signal a larger lubrication problem rather than an isolated dirty solenoid."]},{heading:"Separate signal dropout from stable phase displacement",paragraphs:["An intermittent cam waveform points toward circuit or sensor diagnosis. A repeatable offset with clean signals and timing noise supports hydraulic or mechanical inspection.","Verify correct Bank 2 tracking hot and cold and no pending P0021. A lamp extinguished immediately after clearing is not proof."]}],sources:[wrxService,stis,subaruOwners]}),
 make(wrx,{code:"P0457",slug:"subaru/wrx/p0457",title:"P0457 Code Subaru WRX: Fuel Cap and EVAP Leak Test",description:"Diagnose WRX P0457 through cap evidence, purge and vent sealing, turbo plumbing context and regulated EVAP smoke testing.",definition:"EVAP System Leak Detected (Fuel Cap Loose/Off)",kind:"evapCap",quickAnswer:"P0457 means the WRX EVAP monitor found an opening commonly associated with a loose or missing fuel cap, but the cap is not guaranteed. Preserve the filler condition and fuel level, inspect the seal and neck, test purge and vent operation, validate tank-pressure response, and use regulated EVAP smoke to inspect hoses, canister, tank and pump-module seals. Hard starting after refueling increases purge-leak priority. Modified engine plumbing still requires correct vapor routing.",yearNotes:["EJ, FA20DIT and FA24DIT purge routing and leak-check hardware differ.","Aftermarket intake work can disturb purge and vapor connections.","Fuel-pump access or rear collision history raises tank-seal and line priority.","Fuel level, ambient temperature and soak gate monitor completion."],deepDive:[{heading:"Preserve cap evidence before tightening",paragraphs:["Photograph whether the cap is absent, cross-threaded or insufficiently tightened and inspect the gasket and filler surface. A good-looking cap can still fail a seal test.","If a found-loose cap is corrected and the complete system passes, the evidence supports it. Repeatedly installing caps without testing does not."]},{heading:"Turbo drivability can expose purge leakage",paragraphs:["A purge valve passing manifold vacuum when commanded closed can produce hard starting after refueling and fuel-correction changes. Test sealing, not just coil activation.","Inspect vapor connections disturbed during inlet, manifold or fuel-system modification. Use SSM commands and low regulated smoke to section the system safely."]},{heading:"Monitor completion is final proof",paragraphs:["Record fuel level, soak and temperature because EVAP readiness may take time. Do not top off the tank to force the test, as liquid fuel can damage the canister.","Confirm a passing leak check and completed monitor with no pending P0457. Clearing memory merely postpones the decision."]}],sources:[stis,subaruOwners]}),
 make(wrx,{code:"P0172",slug:"subaru/wrx/p0172",title:"P0172 Code Subaru WRX: Rich Fuel Correction Diagnosis",description:"Diagnose WRX P0172 with injector, low/high fuel pressure, purge, MAF scaling, A/F sensor and oil-dilution tests.",definition:"System Too Rich (Bank 1)",kind:"rich",quickAnswer:"P0172 means the WRX ECM removed excessive fuel from Bank 1. Save correction and learning at idle, cruise and load; inspect labeled plugs and engine oil; test purge leakage, injector sealing and low/high fuel pressure; then validate measured airflow and upstream A/F response. Modified intakes, larger injectors or calibration mismatches can create systematic rich correction. FA direct-injection systems require high-pressure safety. A rising oil level or gasoline odor in the oil warrants limiting operation.",yearNotes:["EJ port injection and FA direct injection use different pressure and injector tests.","WRX modifications and fuel blend must be recorded before interpreting learning.","One-bank patterns on the boxer engine can localize injector or exhaust causes.","Fuel dilution threatens lubrication and catalyst life."],deepDive:[{heading:"Map where the ECM removes fuel",paragraphs:["Compare immediate and learned correction at idle, cruise and safe load. Idle-heavy rich correction favors purge or injector leakage; broad correction raises pressure, airflow scaling or calibration.","Compare boxer banks and labeled plug deposits. A single fuel-wet cylinder is stronger local evidence than a blanket sensor replacement."]},{heading:"Test both fuel stages safely",paragraphs:["For FA engines, graph low-side supply and commanded versus actual rail pressure without opening the high-pressure circuit. For EJ engines, use the applicable port-injection pressure and balance method.","Verify purge closed-state sealing and whether symptoms follow refueling. Excess vapor can enrich the engine even when liquid-fuel pressure is correct."]},{heading:"Reconcile airflow, feedback and modifications",paragraphs:["Inspect the intake and MAF installation, then compare airflow with load and boost. Check exhaust leakage before evaluating the A/F sensor response.","Correct any calibration/hardware mismatch and address confirmed fuel-diluted oil. Verify stable learning and no pending P0172 under the original condition."]}],sources:[subaruCatalyst,stis,subaruOwners]}),
 make(wrx,{code:"P0137",slug:"subaru/wrx/p0137",title:"P0137 Code Subaru WRX: Rear O2 Low-Voltage Diagnosis",description:"Diagnose WRX P0137 with exhaust-leak, mixture, rear-sensor heater and harness tests while respecting Subaru bulletin exclusions.",definition:"O2 Sensor Circuit Low Voltage (Bank 1, Sensor 2)",kind:"rearO2Low",quickAnswer:"P0137 means the WRX Bank 1 downstream oxygen-sensor signal stayed low. Graph rear voltage with upstream A/F correction, inspect the turbo exhaust for air leakage, and load-test signal, ground, heater and heat-exposed wiring before replacing the sensor. Subaru bulletin 09-115-24 covers other named models but does not list WRX, so its revised-sensor branch must not be borrowed for this page. The WRX uses its VIN-correct STIS procedure; P0171, P0300 and P0420 companions take priority.",yearNotes:["09-115-24 does not list WRX among its applicable models.","Turbo exhaust joints and aftermarket downpipes change leak and wiring context.","Rear O2 and upstream A/F sensors have different functions.","P0420 bulletin 09-110-23R treats P0137 as a prerequisite on covered WRXs."],deepDive:[{heading:"A low signal can be real oxygen or circuit loss",paragraphs:["Graph rear voltage after full warm-up alongside upstream correction. A responsive sensor tracking a true lean condition differs from a circuit pinned low regardless of operating change.","Load-test heater supply, signal return and ground while inspecting heat shields, connectors and areas altered by exhaust work. Static continuity may pass through a weak hot connection."]},{heading:"Inspect the turbo exhaust cold",paragraphs:["Check cylinder-head, turbo, downpipe/front-pipe, flange and sensor-bung joints for soot or a cold tick. Outside air ahead of the rear sensor can hold its signal low.","Resolve P0171 and active misfire first. Subaru's catalyst bulletin screens P0137 before it evaluates P0420, preventing sensor or mixture faults from becoming converter diagnoses."]},{heading:"Do not misapply the 2024 sensor bulletin",paragraphs:["Bulletin 09-115-24 lists Legacy/Outback, Impreza/Crosstrek, Forester and BRZ applications, not WRX. Similar code wording does not expand its production boundaries.","Use current WRX STIS and verify plausible hot rear-sensor response with no pending P0137. A universal sensor order would ignore engine and exhaust changes."]}],sources:[subaruRearSensor,subaruCatalyst,stis,subaruOwners]}),
 make(wrx,{code:"P2096",slug:"subaru/wrx/p2096",title:"P2096 Code Subaru WRX: Corrected Post-Catalyst Lean Test",description:"Diagnose WRX P2096 with Subaru's 2015–2025 corrected procedure, upstream trims, exhaust leaks, rear O2 and catalyst evidence.",definition:"Post Catalyst Fuel Trim System Too Lean (Bank 1)",kind:"postCatLean",quickAnswer:"P2096 means the WRX post-catalyst Bank 1 fuel correction reached a lean limit; it does not automatically identify the rear sensor or converter. Save P0171, P0300, P0137 and P0420 companions, upstream learning and rear-sensor data; inspect turbo exhaust leakage; correct upstream mixture and misfire; then test the rear sensor and catalyst. Subaru bulletin 18-228-25 explicitly replaces diagnostic steps 12 and 13 for 2015–2025 WRX.",yearNotes:["18-228-25 lists 2015–2025 WRX and replaces specified service-manual steps.","It is a diagnostic correction, not a sensor or catalyst replacement campaign.","EJ, FA20DIT and FA24DIT fueling and exhaust layouts differ.","P2096 plus P0171 puts upstream lean diagnosis first."],deepDive:[{heading:"Post-catalyst does not mean start downstream",paragraphs:["Review A/F correction, roughness counts, rail pressure and upstream sensor behavior. A real lean mixture or misfire continues through the converter and changes the rear signal.","Test the intake, charge path, purge, MAF and fuel delivery when upstream data is abnormal. A rear sensor cannot repair those causes."]},{heading:"Turbo exhaust leaks can be small but influential",paragraphs:["Inspect head, turbo, flange, weld, flex and sensor-bung joints cold for soot and leakage. Aftermarket exhaust fitment deserves documentation and legal/emissions review.","Then load-test Bank 1 Sensor 2 and compare its response with upstream data. Separate true oxygen from electrical bias before considering catalyst performance."]},{heading:"Use Subaru's corrected steps exactly",paragraphs:["Bulletin 18-228-25 identifies the WRX years and step numbers replaced in STIS. It does not prescribe one part for every car and warns that service information can be updated.","Complete the required monitor after repair. Normal upstream and post-catalyst data with no pending P2096 confirms the result."]}],sources:[subaruPostCat,subaruCatalyst,stis,subaruOwners]})
];

export const troubleCodeElantra:TroubleCodeGuide[]=[
 make(elantra,{code:"P1326",slug:"hyundai/elantra/p1326",title:"P1326 Code Hyundai Elantra: Bearing Campaign vs. Elantra N Water Intrusion",description:"Separate Elantra P1326 bearing-inspection campaign coverage from the Elantra N rain/wash knock-sensor connector bulletin.",definition:"Knock Sensor Detection System / Engine Protection DTC",kind:"hyundaiKsds",quickAnswer:"P1326 on an Elantra requires VIN and engine identification before any repair. Hyundai Campaign T6G includes certain 2014–2016 Elantra MD Nu 2.0L GDI, 2014 Elantra Coupe and specified Elantra GT vehicles for bearing inspection and possible engine/ECU action. A different bulletin covers all 2022–2025 Elantra N when P1326 follows heavy rain or a car wash with no abnormal engine noise; that path replaces the knock sensor and connector. If knocking is present, shut the engine off and tow it—the water-intrusion bulletin explicitly does not apply.",yearNotes:["Campaign T6G coverage is VIN-, body- and engine-specific.","24-EM-010H covers 2022–2025 Elantra N only under wet-condition/no-noise criteria.","A standard Elantra and Elantra N do not share the same automatic repair.","Reduced-power mode is protective and should not be overridden."],deepDive:[{heading:"The same code opens two very different Hyundai paths",paragraphs:["TSB 22-01-023H addresses connecting-rod bearing wear on specified vehicles and directs a measured inspection, engine decision and ECU work through its campaign flowchart. Model name alone does not establish eligibility.","TSB 24-EM-010H addresses water intrusion at the knock-sensor connector on 2022–2025 Elantra N after heavy rain or washing. It states that abnormal engine noise excludes that bulletin."]},{heading:"Noise changes the safety decision",paragraphs:["Heavy knocking, oil-pressure warning, stalling or severe vibration requires shutdown and towing. Repeated restarts can increase damage if a bearing is failing.","A quiet Elantra N in limp mode still needs prompt diagnosis; quiet operation does not justify clearing P1326. Preserve the wet-condition history and GDS report."]},{heading:"VIN lookup and Hyundai tests control the repair",paragraphs:["Use Hyundai's campaign lookup with the full VIN and verify body style, model year and engine. Perform the required bearing-clearance or knock-sensor/connector procedure rather than substituting a universal sensor test.","Verification includes completion of campaign or bulletin steps, required adaptive reset/ECU action, normal engine behavior and no returning P1326. Keep repair documentation for future warranty history."]}],sources:[bearing,nWater,campaigns,htech,hyundaiOwners]}),
 make(elantra,{code:"P0014",slug:"hyundai/elantra/p0014",title:"P0014 Code Hyundai Elantra: Exhaust CVVT Over-Advanced",description:"Diagnose Elantra P0014 with oil checks, exhaust OCV command, desired/actual cam angle and crank/cam waveform evidence.",definition:"Exhaust Camshaft Position Timing Over-Advanced/System Performance (Bank 1)",kind:"hyundaiVvt",quickAnswer:"P0014 means the Elantra's exhaust cam remained more advanced than commanded or failed CVVT performance. Identify the Beta, Gamma, Nu, Smartstream or N powertrain; save desired/actual exhaust angle, oil temperature and P0017 companions; verify oil, filter and pressure; then test the exhaust oil-control valve, circuit and cam response. On an inline-four, Bank 1 is the only bank and Sensor B is the exhaust cam. Do not replace a sensor, solenoid or timing chain until waveform and command evidence separates them.",yearNotes:["Elantra engines differ in intake-only versus dual CVVT hardware.","P0017 with P0014 raises exhaust phaser/indexing and mechanical timing priority.","Low or wrong oil can prevent the cam from returning to base position.","Elantra N and Hybrid powertrains require their own shop-manual procedure."],deepDive:[{heading:"Start with exhaust desired versus actual angle",paragraphs:["Record both cam positions at idle, during GDS actuation and near the freeze-frame condition. An exhaust-only error narrows the OCV, passage, phaser, sensor and indexing branches.","If intake and exhaust codes occur together, inspect shared oil supply, pressure, voltage and base timing before assuming two valves failed."]},{heading:"Test the OCV circuit and hydraulic result separately",paragraphs:["Load-test power, control and terminal fit, measure current, then confirm the exhaust cam moves and returns. A clicking valve can remain hydraulically restricted.","Inspect the oil and approved screens/passages for contamination. Correct the cause of sludge or low pressure rather than merely cleaning evidence away."]},{heading:"Use P0017 and waveform phase to choose repair depth",paragraphs:["Missing or noisy sensor edges favor circuit diagnosis. Clean signals with a fixed crank-to-exhaust-cam offset and timing noise support phaser, indexing or chain inspection.","Perform any required learning after repair and verify commanded tracking hot and cold with no pending P0014."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0017",slug:"hyundai/elantra/p0017",title:"P0017 Code Hyundai Elantra: Exhaust Cam Correlation Diagnosis",description:"Diagnose Elantra P0017 by scoping crank and exhaust cam signals, testing CVVT response and proving mechanical indexing.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1, Sensor B)",kind:"hyundaiCorrelation",quickAnswer:"P0017 means the Elantra ECM found the Bank 1 exhaust cam out of its expected relationship with the crankshaft. It does not prove either position sensor failed. Save P0014/P0016 and desired/actual cam data, verify oil and pressure, scope crank with both cams, and command exhaust CVVT. Signal dropout points toward wiring or sensors; clean signals with a stable phase displacement point toward the phaser, cam indexing, reluctor or timing drive. Use the exact engine manual before removing the cover.",yearNotes:["Sensor B is the exhaust-cam branch on Elantra inline-four engines.","Nu, Gamma, Smartstream and Theta-family timing layouts differ.","P0016 plus P0017 suggests shared base timing more strongly than exhaust-only P0017.","Startup rattle, stalling or no-start increases urgency."],deepDive:[{heading:"A correlation code reports a relationship",paragraphs:["The ECM compares crank edges with the exhaust-cam reference while accounting for commanded CVVT. Replacing both sensors does not correct a phaser or chain that is physically out of position.","Save hot/cold behavior and companion codes. P0014 plus P0017 focuses the exhaust-control branch; intake and exhaust correlation together raises base timing."]},{heading:"Scope first, then inspect mechanics",paragraphs:["Look for missing edges, noise and voltage drop while cranking and idling. A repeatable angular offset with clean waveforms is different evidence from an intermittent open circuit.","Command the exhaust OCV and compare desired/actual angle. Verify oil pressure before interpreting slow hydraulic response as a mechanical failure."]},{heading:"Physical indexing must be VIN-correct",paragraphs:["If waveform evidence supports misalignment, follow Hyundai's engine-specific TDC, chain-mark, phaser and cam-index inspection. Do not transfer procedures or torque values across Nu, Gamma or Smartstream engines.","Verify stable crank/exhaust phase at cold start and operating temperature with no pending P0017. An immediate code clear is not confirmation."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0300",slug:"hyundai/elantra/p0300",title:"P0300 Code Hyundai Elantra: Misfire Diagnosis and Bulletin Limits",description:"Diagnose Elantra P0300 with cylinder counts, plugs, coils, injectors, fuel trims and two narrowly bounded Hyundai bulletins.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple Elantra cylinders misfired or no one cylinder dominated. Preserve P0301–P0304 counts, fuel correction, temperature and load. Hyundai TSB 20-FL-001H is limited to certain 2017 AD/ADA 2.0L cars and combines ECM updating with coil inspection. TSB 24-FL-006H covers only a production-bounded group of 2022 Elantra N 2.0T vehicles for internal injector-filter breakage. Other Elantras need plug, ignition, injector, air/fuel, compression and timing tests—not borrowed bulletin repairs.",yearNotes:["20-FL-001H is a 2017 AD/ADA 2.0L branch.","24-FL-006H covers selected 2022 Elantra N production/VIN-origin vehicles.","MPI, GDI and turbo engines require different fuel-safety procedures.","A flashing MIL means stop loading the catalyst."],deepDive:[{heading:"Bulletin eligibility is part of diagnosis",paragraphs:["For a 2017 2.0L AD/ADA, verify VIN, ROM and coil inspection criteria before applying Event 583 or its later replacement. The bulletin does not cover every model year.","For a 2022 Elantra N, production date and VIN origin determine the injector branch. Its all-four-injector instruction should not be generalized to another engine."]},{heading:"Preserve the cylinder pattern",paragraphs:["Record cold-start, idle and loaded counts, then label plugs and move only one ignition part when a controlled comparison is valid. One-cylinder, paired-cylinder and all-cylinder patterns lead to different tests.","If the fault stays, evaluate injector contribution, low/high fuel pressure and compression/leak-down. GDI hardware retains hazardous pressure."]},{heading:"Verify combustion before catalyst judgment",paragraphs:["Inspect intake leaks, purge behavior, fuel correction and P0014/P0017 timing context. Shared mixture or timing faults can look like several failed coils.","Confirm stable counts under the original safe condition and no pending P0300. Any P0420 evaluation follows only after misfire is gone."]}],sources:[misfire17,nInjectors,htech,hyundaiOwners]}),
 make(elantra,{code:"P0420",slug:"hyundai/elantra/p0420",title:"P0420 Code Hyundai Elantra: Catalyst Prerequisite Diagnosis",description:"Diagnose Elantra P0420 by proving misfire, fuel correction, oil consumption, exhaust integrity and sensor response first.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means the Elantra ECM calculated that its Bank 1 catalyst stored less oxygen than expected. Elantra inline-fours have one bank, but catalyst and sensor packaging differs by engine. Save P0300, P0171/P0172 and oxygen-sensor companions; repair misfire, injector imbalance, rich/lean control and oil/coolant consumption; inspect exhaust leakage; then test upstream and downstream sensor response under Hyundai's enable conditions. A rear trace resembling the front is evidence, not an automatic converter order.",yearNotes:["Elantra inline-fours use Bank 1 only.","Close-coupled and underfloor catalyst arrangements vary by engine and emissions package.","Active misfire or rich operation can overheat the converter rapidly.","Aftermarket exhaust components must meet applicable emissions law and monitor requirements."],deepDive:[{heading:"Find what may have damaged the catalyst",paragraphs:["Review permanent misfire, mixture and airflow codes, labeled plug deposits and injector balance. A converter can be the victim of a fault that will damage the replacement too.","Document oil additions and coolant loss. Ash and contamination can reduce oxygen-storage capacity even after the engine appears to run normally."]},{heading:"Inspect the exhaust and sensor circuits cold",paragraphs:["Check manifold, flex, flanges, welds and sensor bungs for soot, ticking or looseness. Outside oxygen can distort the efficiency calculation.","Verify upstream and rear sensor heater, wiring and response. A switching rear signal does not distinguish substrate loss from a leak or abnormal combustion by itself."]},{heading:"Run the monitor only after prerequisites pass",paragraphs:["Use Hyundai TechInfo for the engine-specific temperature, load and readiness path. Do not evaluate catalyst storage while fuel correction or misfire remains abnormal.","Final confirmation is a completed catalyst monitor without pending P0420. Clearing codes resets readiness and delays that proof."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0456",slug:"hyundai/elantra/p0456",title:"P0456 Code Hyundai Elantra: Very Small EVAP Leak Test",description:"Diagnose Elantra P0456 with cap evidence, purge and canister-close sealing, tank-pressure data and regulated smoke.",definition:"EVAP System Very Small Leak Detected",kind:"hyundaiEvap",quickAnswer:"P0456 means the Elantra EVAP system failed a very-small-leak monitor; it does not prove the cap or purge valve failed. Preserve fuel level, cap and refueling evidence, inspect filler and vapor routing, command purge and canister-close operation, validate tank-pressure response, and use regulated EVAP smoke to section the system. Hard starting after refueling favors purge leakage. Software bulletins for another Hyundai model or engine must not be extended to an Elantra without exact VIN and ROM applicability.",yearNotes:["EVAP hardware changes across MD/UD, AD and CN7 generations.","Hybrid, turbo and N applications require their own vapor-routing diagrams.","Recent fuel-pump, tank or collision work raises top-of-tank and line priority.","Fuel level and overnight soak gate the monitor."],deepDive:[{heading:"Start with found condition, not a parts-store reset",paragraphs:["Record cap tightness, gasket and filler-neck condition before changing anything. Note the fuel level and whether the lamp followed refueling or tank service.","A cap that looks intact can fail its sealing test, while a new cap cannot repair a purge, close-valve, hose or module seal leak."]},{heading:"Valves must seal as well as actuate",paragraphs:["Command purge and canister-close components with GDS and test actual airflow or vacuum. Clicking only confirms movement, not a gas-tight seat.","Graph tank-pressure response and use low regulated smoke to section the filler, canister and tank branches. Never apply unrestricted shop air."]},{heading:"Complete readiness after the leak is proven repaired",paragraphs:["Meet Hyundai's fuel-level, temperature and soak prerequisites rather than overfilling the tank. Topping off can saturate the canister.","A passing pressure/leak test and completed EVAP monitor with no pending P0456 confirm repair. An extinguished lamp with incomplete readiness does not."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0011",slug:"hyundai/elantra/p0011",title:"P0011 Code Hyundai Elantra: Intake CVVT Over-Advanced",description:"Diagnose Elantra P0011 with oil, intake OCV circuit, commanded/actual angle and cam/crank correlation testing.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 1)",kind:"hyundaiVvt",quickAnswer:"P0011 means the Elantra intake cam remained more advanced than commanded or failed CVVT performance. Confirm the exact engine, save desired/actual intake angle and P0016/P0017 companions, verify oil, filter and pressure, then test the intake oil-control valve, wiring and actual cam response. On an inline-four, Bank 1 is the only bank and Sensor A is the intake cam. Do not assume a solenoid will repair restricted oil flow, a sticking phaser, incorrect indexing or a noisy sensor signal.",yearNotes:["Some early Elantra engines have different CVVT coverage from later dual-CVVT engines.","Nu, Gamma, Smartstream and Elantra N hardware cannot share procedures blindly.","P0011 with P0014 raises shared oil and base-timing priority.","Low oil pressure or persistent chain noise requires stopping."],deepDive:[{heading:"Graph the intake cam before removing parts",paragraphs:["Record desired and actual position at idle and during GDS actuation. Compare exhaust response only under the same oil temperature and rpm.","An intake-only failure supports its OCV, passage, phaser and feedback branch. Both cams abnormal shifts attention to shared lubrication, voltage or base timing."]},{heading:"Prove electrical command and hydraulic movement",paragraphs:["Load-test OCV power, control and terminal grip, measure current, and watch cam movement. A normal resistance value cannot prove that oil reaches or leaves the phaser correctly.","Inspect oil quality and engine-specific screens/passages. Contamination should trigger root-cause work, not a superficial cleaning-only repair."]},{heading:"Correlation signals decide whether teardown is justified",paragraphs:["Missing or noisy cam edges favor circuit diagnosis. Clean signals with a stable phase displacement and rattle support phaser, reluctor or timing inspection.","After repair, perform required learning and verify intake angle tracks command hot and cold with no pending P0011."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0128",slug:"hyundai/elantra/p0128",title:"P0128 Code Hyundai Elantra: Thermostat Warm-Up Diagnosis",description:"Diagnose Elantra P0128 with cold ECT/IAT comparison, coolant and fan checks, warm-up graph and exact thermostat identification.",definition:"Coolant Thermostat — Temperature Below Regulating Temperature",kind:"warmup",quickAnswer:"P0128 means the Elantra coolant temperature did not rise or regulate as the ECM expected. A leaking-open thermostat is common, but low coolant, trapped air, biased ECT data, unintended fan operation or an incorrect thermostat can imitate it. Compare ECT and intake-air temperature after a long soak, inspect coolant only when cold, then graph temperature, road speed, engine load and fan command. Hybrid and turbo cooling strategies need their own service mode and bleed procedure.",yearNotes:["Thermostat temperature, housing and bleed process differ by engine.","The dashboard gauge is damped and cannot replace scan data.","Hybrid engine-off operation changes warm-up interpretation.","Stop for overheating, steam, coolant loss or suddenly cold heater output."],deepDive:[{heading:"Cold-soak data tests the sensors before the thermostat",paragraphs:["After an overnight soak, ECT and intake-air temperature should approach ambient. A large mismatch exists before coolant circulation begins and raises sensor or circuit priority.","Check reservoir/radiator level only by the manual's cold procedure and inspect recent cooling work for trapped air or leakage."]},{heading:"Graph temperature against speed and fan command",paragraphs:["A thermostat leaking open may warm slowly in town and let temperature fall during highway airflow. Record speed, load, cabin heat and ambient conditions.","Verify commanded versus actual fan operation. A relay or control fault that runs fans cold can produce the same slow warm-up pattern."]},{heading:"Install the engine-correct part and verify regulation",paragraphs:["Elantra engine families do not share thermostat ratings or fill procedures. Identify VIN and engine before draining coolant.","Confirm stable temperature and heater performance under comparable conditions and no pending P0128. A cleared code immediately after installation proves nothing."]}],sources:[htech,hyundaiOwners]}),
 make(elantra,{code:"P0301",slug:"hyundai/elantra/p0301",title:"P0301 Code Hyundai Elantra: Cylinder 1 Misfire Diagnosis",description:"Diagnose Elantra P0301 with cylinder location, labeled plug, controlled coil test, injector, compression and bulletin applicability.",definition:"Cylinder 1 Misfire Detected",kind:"cyl1",quickAnswer:"P0301 localizes misfire to Elantra cylinder 1 but does not identify the coil. Confirm cylinder numbering from the exact engine manual, preserve cold/load counts, inspect the labeled plug and make one controlled ignition comparison. If the fault stays, test injector delivery and compression/leak-down. Hyundai's 2017 AD/ADA 2.0L bulletin and selected 2022 Elantra N injector bulletin have strict applicability; neither authorizes the same repair on every Elantra P0301.",yearNotes:["20-FL-001H covers certain 2017 AD/ADA 2.0L vehicles.","24-FL-006H covers a production-bounded group of 2022 Elantra N vehicles.","MPI and GDI injector tests require different equipment and safety.","P0017 or P0014 companions raise timing priority."],deepDive:[{heading:"Use one controlled ignition test",paragraphs:["Keep plug 1 labeled and compare gap, deposits, cracking and fuel wetness with a neighboring cylinder. Move one known-good coil only when the hardware permits and monitor whether the count follows.","If P0301 stays on cylinder 1, return the known-good component. Further swapping destroys evidence and does not test fuel or compression."]},{heading:"Test injector and sealing when ignition passes",paragraphs:["Use GDS contribution and engine-specific pressure/balance methods. Direct-injection fuel components retain dangerous pressure and require factory procedures.","Measure compression and leak-down under comparable temperature. Valve sealing, cylinder damage or cam timing can keep the count on one hole."]},{heading:"Apply Hyundai bulletins only at their boundaries",paragraphs:["The 2017 bulletin combines ECM logic and coil inspection for its exact AD/ADA 2.0L branch. The 2022 N bulletin concerns selected injectors by production data.","Verify no cylinder 1 counts under the original safe condition and no pending P0301. A software update cannot restore compression or seal an injector."]}],sources:[misfire17,nInjectors,htech,hyundaiOwners]}),
 make(elantra,{code:"P200A",slug:"hyundai/elantra/p200a",title:"P200A Code Hyundai Elantra: Intake Runner Performance Diagnosis",description:"Diagnose Elantra P200A by identifying the manifold design and testing actuator command, position feedback, linkage, deposits and circuits.",definition:"Intake Manifold Runner Performance (Bank 1)",kind:"intakeRunner",quickAnswer:"P200A means the applicable Elantra intake-runner or variable-induction system on Bank 1 did not reach expected performance. Not every Elantra engine uses the same actuator, position feedback, linkage or vacuum control, so identify the engine and manifold first. Save runner command, position, rpm and load; inspect external linkage and connectors; command the actuator with GDS; test position feedback and wiring; then inspect internal flap travel or deposits only as evidence directs. Do not automatically replace the complete manifold.",yearNotes:["Elantra inline-fours have one bank, so Bank 1 is the only bank.","Runner hardware differs across Beta, Gamma, Nu, Smartstream and turbo engines.","Some designs use an electric actuator while others may use vacuum control.","Manifold removal can require new gaskets and engine-specific fuel safety."],deepDive:[{heading:"First identify what the installed manifold uses",paragraphs:["Decode VIN and engine, then use Hyundai TechInfo to locate actuator, position sensor, linkage and any vacuum solenoid. Searching by Elantra alone can produce a component that another engine does not contain.","Save commanded and actual runner position at the freeze-frame rpm and load. An immediate code points more toward circuit/feedback; load-dependent failure raises sticking or incomplete travel."]},{heading:"Observe command, current and physical movement together",paragraphs:["Command the system with GDS while watching linkage and position feedback. An audible motor does not prove the shaft reaches both stops.","Load-test power, ground, control and signal, and inspect disconnected linkage or excessive shaft play. If vacuum operated, verify supply and solenoid sealing with the specified method."]},{heading:"Internal deposits are a measured conclusion",paragraphs:["If external command and linkage pass but travel remains restricted, inspect the runners and bores under the engine-specific procedure. Carbon may bind the mechanism, but cleaning cannot repair a broken shaft or failed sensor.","After repair, verify full commanded travel under the original operating condition and no pending P200A. Replace the full manifold only when its non-serviceable mechanism is proven faulty."]}],sources:[htech,hyundaiOwners]})
];
